-- ds_problem_flow — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_problem_flow.
-- Problems raised and closed, one row per event. Triage: Raised vs closed per week.

SELECT date_trunc('WEEK', raised_ts) AS week, 'Raised' AS flow, cohort_id, severity,
       business_domain
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_cohort_current
UNION ALL
SELECT date_trunc('WEEK', CASE WHEN lifecycle_state = 'closed_verified' THEN verified_ts
                               ELSE reviewed_ts END),
       'Closed', cohort_id, severity, business_domain
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_cohort_current
WHERE  lifecycle_state LIKE 'closed%'
